<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import { api,errorText,loadPage } from '../api/http'
import { useAuthStore } from '../stores/auth'
import { dateTime } from '../utils/format'
import type { Row } from '../types'
const route=useRoute(),auth=useAuthStore(),resource=computed(()=>String(route.meta.resource)),title=computed(()=>({users:'用户管理',roles:'角色与权限',logs:'操作日志'}[resource.value]||'')),path=computed(()=>resource.value==='logs'?'/system/operation-logs':`/system/${resource.value}`)
const rows=ref<Row[]>([]),q=ref(''),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),enabled=ref<boolean>(),success=ref<boolean>(),module=ref(''),dates=ref<string[]>([]),drawer=ref(false),mode=ref(''),selected=ref<Row|null>(null),busy=ref(false),formError=ref(''),roles=ref<Row[]>([]),permissions=ref<Row[]>([])
const form=reactive<Row>({})
const canWrite=computed(()=>auth.can(resource.value==='users'?'system:user:write':'system:role:write'))
const modules:Record<string,string>={system:'系统管理',master:'基础资料',erp:'采购与销售',mes:'生产管理',wms:'仓储管理',workbench:'工作台'}
const permissionGroups=computed(()=>Object.entries(modules).map(([key,label])=>({key,label,items:permissions.value.filter(p=>p.module===key)})).filter(g=>g.items.length))
async function load(){loading.value=true;error.value='';try{const params:Row={page:page.value,size:20};if(resource.value==='logs')Object.assign(params,{success:success.value,module:module.value||undefined,from:dates.value?.[0]?new Date(dates.value[0]).toISOString():undefined,to:dates.value?.[1]?new Date(dates.value[1]).toISOString():undefined});else Object.assign(params,{q:q.value||undefined,enabled:resource.value==='users'?enabled.value:undefined});const result=await loadPage<Row>(path.value,params);rows.value=result.items;total.value=Number(result.total)}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function allRoles(){if(!auth.can('system:role:read'))return;let p=1;let result;const list:Row[]=[];do{result=await loadPage<Row>('/system/roles',{page:p++,size:100});list.push(...result.items)}while(list.length<Number(result.total));roles.value=list}
async function open(operation:string,row?:Row){formError.value='';mode.value=operation;try{selected.value=row?(await api.get(`${path.value}/${row.id}`)).data:null;Object.assign(form,{username:'',displayName:'',initialPassword:'',newPassword:'',enabled:true,roleIds:[],code:'',name:'',description:'',permissionCodes:[]},selected.value||{});if(resource.value==='users')await allRoles();if(operation==='permissions')permissions.value=(await api.get('/system/permissions')).data;drawer.value=true}catch(e){error.value=errorText(e)}}
async function save(){if(busy.value)return;busy.value=true;formError.value='';try{
  if(resource.value==='users'){
    if(mode.value==='roles')await api.put(`${path.value}/${selected.value!.id}/roles`,{version:selected.value!.version,roleIds:form.roleIds})
    else if(mode.value==='reset')await api.post(`${path.value}/${selected.value!.id}/reset-password`,{version:selected.value!.version,newPassword:form.newPassword})
    else if(selected.value)await api.put(`${path.value}/${selected.value.id}`,{version:selected.value.version,displayName:form.displayName,enabled:form.enabled})
    else await api.post(path.value,{username:form.username,displayName:form.displayName,initialPassword:form.initialPassword,enabled:form.enabled,roleIds:form.roleIds})
  }else if(mode.value==='permissions')await api.put(`${path.value}/${selected.value!.id}/permissions`,{version:selected.value!.version,permissionCodes:form.permissionCodes})
  else{const body:Row={code:form.code,name:form.name,description:form.description};if(selected.value){body.version=selected.value.version;await api.put(`${path.value}/${selected.value.id}`,body)}else await api.post(path.value,body)}
  ElMessage.success('保存成功');drawer.value=false;await auth.load();await load()
}catch(e){formError.value=errorText(e)}finally{form.initialPassword='';form.newPassword='';busy.value=false}}
async function remove(row:Row){try{await ElMessageBox.confirm(`删除自定义角色「${row.name}」？已分配用户的角色不能删除。`,'删除角色',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});busy.value=true;await api.delete(`${path.value}/${row.id}`,{params:{version:row.version}});await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
watch(resource,()=>{q.value='';page.value=1;enabled.value=undefined;dates.value=[];module.value='';success.value=undefined;drawer.value=false;void load()},{immediate:true})
</script>
<template><div class="page-header"><div><h1>{{title}}</h1></div><el-button v-if="resource!=='logs'&&canWrite" type="primary" @click="open('edit')">新建{{resource==='users'?'用户':'角色'}}</el-button></div><section class="panel"><form class="filters" @submit.prevent="page=1;load()"><template v-if="resource!=='logs'"><el-input v-model="q" placeholder="搜索账号、编码或名称" aria-label="搜索账号编码名称" clearable/><el-select v-if="resource==='users'" v-model="enabled" placeholder="全部状态" clearable><el-option label="启用" :value="true"/><el-option label="停用" :value="false"/></el-select></template><template v-else><el-select v-model="module" placeholder="全部模块" clearable><el-option v-for="(name,key) in modules" :key="key" :label="name" :value="key"/></el-select><el-select v-model="success" placeholder="全部结果" clearable><el-option label="成功" :value="true"/><el-option label="失败" :value="false"/></el-select><el-date-picker v-model="dates" type="datetimerange" start-placeholder="起始时间" end-placeholder="结束时间"/></template><el-button type="primary" native-type="submit">查询</el-button><el-button @click="q='';enabled=undefined;module='';success=undefined;dates=[];page=1;load()">重置</el-button></form><div v-if="error" class="error-box" role="alert">{{error}} <el-button link @click="load">重试</el-button></div><el-table :data="rows" v-loading="loading" empty-text="暂无记录"><template v-if="resource==='users'"><el-table-column prop="username" label="账号" min-width="170"/><el-table-column prop="displayName" label="姓名" min-width="150"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag size="small" :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="创建时间" min-width="175"><template #default="{row}">{{dateTime(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="255" fixed="right"><template #default="{row}"><el-button v-if="canWrite" link type="primary" @click="open('edit',row)">编辑 / 启停</el-button><el-button v-if="canWrite&&auth.can('system:role:read')" link @click="open('roles',row)">分配角色</el-button><el-button v-if="canWrite" link @click="open('reset',row)">重置密码</el-button></template></el-table-column></template><template v-else-if="resource==='roles'"><el-table-column prop="code" label="角色编码" min-width="150"/><el-table-column prop="name" label="角色名称" min-width="140"/><el-table-column prop="description" label="说明" min-width="200"/><el-table-column label="类型" width="100"><template #default="{row}">{{row.builtin?'内置角色':'自定义'}}</template></el-table-column><el-table-column label="权限数" width="100" align="right"><template #default="{row}">{{row.permissionCodes.length}}</template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button v-if="canWrite" link type="primary" @click="open('edit',row)">编辑</el-button><el-button link @click="open('permissions',row)">{{canWrite?'分配权限':'查看权限'}}</el-button><el-button v-if="canWrite&&!row.builtin" link type="danger" :disabled="busy" @click="remove(row)">删除</el-button></template></el-table-column></template><template v-else><el-table-column label="时间" width="175"><template #default="{row}">{{dateTime(row.occurredAt)}}</template></el-table-column><el-table-column prop="actorName" label="操作者" width="110"/><el-table-column label="模块" width="105"><template #default="{row}">{{modules[row.module]||row.module}}</template></el-table-column><el-table-column prop="action" label="动作" width="105"/><el-table-column prop="resourceType" label="业务对象" min-width="165"/><el-table-column prop="resourceId" label="对象 ID" width="95"/><el-table-column label="结果" width="85"><template #default="{row}"><el-tag size="small" :type="row.success?'success':'danger'">{{row.success?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column prop="summary" label="摘要" min-width="130"/><el-table-column prop="errorCode" label="错误码" min-width="145"/><el-table-column prop="traceId" label="追踪号" min-width="270"/></template></el-table><div class="table-footer"><span v-if="resource==='users'">停用、改密或授权变更会及时影响已有会话</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></div></section>
<el-drawer v-model="drawer" :title="mode==='permissions'?'角色权限分配':mode==='roles'?'分配用户角色':mode==='reset'?'重置登录密码':`${selected?'编辑':'新建'}${resource==='users'?'用户':'角色'}`" size="min(620px,100%)" destroy-on-close @closed="form.initialPassword='';form.newPassword='' "><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="save"><template v-if="mode==='permissions'"><el-alert type="info" :closable="false" title="权限点由代码固定；可写动作需对应查看权限，BOM / 工单还需关联资料查看权限。"/><el-alert v-if="form.code==='ADMIN'" type="warning" :closable="false" title="管理员权限全集固定，不可削减。"/><el-checkbox-group v-model="form.permissionCodes" :disabled="!canWrite||form.code==='ADMIN'"><div v-for="group in permissionGroups" :key="group.key" class="permission-group"><h3>{{group.label}}</h3><el-checkbox v-for="p in group.items" :key="p.code" :value="p.code">{{p.name}}<small>{{p.code}}</small></el-checkbox></div></el-checkbox-group></template><template v-else-if="mode==='roles'"><p>{{form.displayName}} · {{form.username}}</p><el-form-item label="角色"><el-select v-model="form.roleIds" multiple filterable placeholder="选择角色" style="width:100%" aria-label="分配角色"><el-option v-for="r in roles" :key="r.id" :value="r.id" :label="`${r.name} (${r.code})`"/></el-select></el-form-item></template><template v-else-if="mode==='reset'"><el-alert type="warning" :closable="false" title="重置密码后，该用户旧会话失效。"/><el-form-item label="新密码（12～64字符，UTF-8最多72字节）" required><el-input v-model="form.newPassword" type="password" show-password aria-label="重置新密码" autocomplete="new-password"/></el-form-item></template><template v-else-if="resource==='users'"><el-form-item label="账号" required><el-input v-model="form.username" aria-label="用户账号" :disabled="!!selected" :maxlength="50"/></el-form-item><el-form-item label="姓名" required><el-input v-model="form.displayName" aria-label="用户姓名" :maxlength="80"/></el-form-item><el-form-item v-if="!selected" label="初始密码（12～64字符，UTF-8最多72字节）" required><el-input v-model="form.initialPassword" type="password" show-password aria-label="初始密码" autocomplete="new-password"/></el-form-item><el-form-item v-if="!selected&&auth.can('system:role:read')" label="角色"><el-select v-model="form.roleIds" multiple filterable placeholder="选择角色" style="width:100%"><el-option v-for="r in roles" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><el-form-item label="账号启用"><el-switch v-model="form.enabled" active-text="启用" inactive-text="停用"/></el-form-item></template><template v-else><el-form-item label="角色编码" required><el-input v-model="form.code" aria-label="角色编码" :disabled="!!selected" :maxlength="40" placeholder="大写字母、数字和下划线"/></el-form-item><el-form-item label="角色名称" required><el-input v-model="form.name" aria-label="角色名称" :maxlength="80"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" aria-label="角色说明" :maxlength="255" type="textarea"/></el-form-item></template><div class="form-footer"><el-button @click="drawer=false">关闭</el-button><el-button v-if="canWrite&&!(mode==='permissions'&&form.code==='ADMIN')" type="primary" native-type="submit" :loading="busy">保存</el-button></div></el-form></el-drawer></template>
<style scoped>.permission-group{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-bottom:1px solid #edf0f4;padding:12px 0}.permission-group h3{grid-column:1/-1;font-size:14px;line-height:1.6;margin:5px 0 14px}.permission-group .el-checkbox{display:inline-flex;min-width:0;width:100%;margin-right:0;height:auto;margin-bottom:16px;align-items:flex-start}.permission-group small{display:block;color:#96a1b2;font-size:10px;margin-top:3px}</style>
